    "sql": "SELECT m.first_name, m.last_name FROM 'csv/member.csv' AS m JOIN (SELECT unnest(records) AS r FROM read_json_auto('json/zip_code.json')) AS z ON m.zip = z.r.zip_code WHERE z.r.short_state = 'IL'",
    "limit": 200
  }
}
